#!/usr/bin/env bash
# Bundle item 189_pa37_post_video (thread "Videos: make meeting videos", 23 Nov 2569, asked by "Site: Update automatically three times a day")
# Puts the AFTER-meeting video of Public Administration main meeting 37/2569 (Wed 18 Nov 2569, 13.00, CA 426) on
# committee-archive-2569, next to the live before-meeting video of the same meeting (same pattern as 36_pa36_post_video):
#   - files media/v37post.mp4 (1080x1920, Thai voice + English subtitles burned in, one version only), media/v37post.th.vtt,
#     img/poster37post.jpg (720x1280 from cover_9x16.png)
#   - meeting 37 "media" in index.html DATA and meetings.json: video = after-meeting, videos = [after, before];
#     the before-meeting video keeps its files and share page (media/v37.*, img/poster37.jpg, s/v-37-pre.html): nothing renamed
#   - CAPS track "37" (Thai captions; English is burned in), put right before "37p" as the live page has "36" before "36p"
#   - share page s/v-37.html + large-text card (video_share.py, CARD_BIG=1); every existing share page kept byte-identical
#   - home page "latest videos" list (newest 4 by meeting date; the after video goes right before the before video)
#   - shared build source archive/build/build.py VIDEOS[37] becomes [after, before] (best effort; never blocks the site change)
# Source: the published press release ข่าวประชาสัมพันธ์ ครั้งที่ 37/2569 (ref 11232488, Rpublic 1) + notice ว ๑๐๒๖; it prints the
# date as "19 พฤศจิกายน" but the notice and the Senate list say Wed 18 Nov 2569, so the video says 18 (as the site card does).
# Names only the committee chair and the three subcommittee chairs; no complainant or candidate names; complaints marked
# "ยังไม่ใช่ข้อยุติ". Legal check STOP 0 / WARN 0; legal pack kept with the video thread. Auto-approved video (Sukit 9 Nov 2569).
# Runs AFTER item 188_pa37_summary (the routine's order). It works either way: it only sets the meeting's media, and build.py
# carries the video for any later full rebuild.
#
# SELF-CONTAINED: the 3 files are embedded at the end of this file (base64 tar.gz, sha256 checked).
# Idempotent; no git, no network. Needs $HUB $A69 $BUILD.
set -euo pipefail
T=189_pa37_post_video
: "${HUB:?HUB not set}"; : "${A69:?A69 not set}"; : "${BUILD:?BUILD not set}"
SITE_SRC="${SITE_SRC:-/mnt/project-files/archive/site}"   # override only for tests
SELF="${BASH_SOURCE[0]}"
PSHA=60ed69eb1a9ffffc44a8726199ce696bf3bfe598bd4981ce41d31a31a97f649f
export DUR=5:01 T_NAME=189_pa37_post_video
for f in index.html meetings.json; do test -f "$A69/$f" || { echo "$T: A69/$f missing" >&2; exit 1; }; done
test -f "$HUB/index.html" || { echo "$T: hub index.html missing" >&2; exit 1; }

# 0) meeting 37 (2026-11-18) must be on the page once, with its before-meeting video; stop before touching anything if not
python3 - "$A69" <<'PY' || { echo "$T: meeting 37 (18 Nov 2569) is not on the archive page as expected; nothing changed" >&2; exit 1; }
import json, os, sys
A69 = sys.argv[1]; dec = json.JSONDecoder()
sj = json.load(open(os.path.join(A69, 'meetings.json'), encoding='utf-8'))
hit = [m for m in sj if (m['n'], m['date']) == (37, '2026-11-18')]
assert len(hit) == 1
assert any(v.get('src') == 'media/v37.mp4' for v in (hit[0].get('media') or {}).get('videos') or [])
l = [x for x in open(os.path.join(A69, 'index.html'), encoding='utf-8').read().split('\n') if x.startswith('const DATA=')]
assert len(l) == 1
d, _ = dec.raw_decode(l[0][len('const DATA='):])
assert len([m for m in d if (m['n'], m['date']) == (37, '2026-11-18')]) == 1
PY

TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
awk 'f{print} /^__PAYLOAD_BELOW__$/{f=1}' "$SELF" | base64 -d > "$TMP/p.tgz"
echo "$PSHA  $TMP/p.tgz" | sha256sum -c --quiet - || { echo "$T: embedded payload broken (sha256 differs)" >&2; exit 1; }
tar -xzmf "$TMP/p.tgz" -C "$TMP"
W="$TMP/web"
dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$W/v37post.mp4")
python3 -c "import sys; m,s=map(int,'$DUR'.split(':')); d=float('$dur'); sys.exit(0 if abs(d-(60*m+s))<1.0 else 1)" || { echo "$T: v37post.mp4 length $dur, expected ~$DUR" >&2; exit 1; }
wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$W/v37post.mp4"); [ "$wh" = "1080,1920" ] || { echo "$T: v37post.mp4 size $wh" >&2; exit 1; }
head -1 "$W/v37post.th.vtt" | grep -q '^WEBVTT' || { echo "$T: v37post.th.vtt header" >&2; exit 1; }

# 1) files into the archive (and, best effort, the shared build source so a later full rebuild keeps them)
mkdir -p "$A69/media" "$A69/img"
for f in v37post.mp4 v37post.th.vtt; do cmp -s "$W/$f" "$A69/media/$f" || cp -f "$W/$f" "$A69/media/$f"; cmp -s "$W/$f" "$A69/media/$f"; done
cmp -s "$W/poster37post.jpg" "$A69/img/poster37post.jpg" || cp -f "$W/poster37post.jpg" "$A69/img/poster37post.jpg"; cmp -s "$W/poster37post.jpg" "$A69/img/poster37post.jpg"
SRC_OK=1
for f in v37post.mp4 v37post.th.vtt; do cmp -s "$W/$f" "$SITE_SRC/media/$f" 2>/dev/null || cp -f "$W/$f" "$SITE_SRC/media/$f" 2>/dev/null || SRC_OK=0; done
cmp -s "$W/poster37post.jpg" "$SITE_SRC/img/poster37post.jpg" 2>/dev/null || cp -f "$W/poster37post.jpg" "$SITE_SRC/img/poster37post.jpg" 2>/dev/null || SRC_OK=0
[ "$SRC_OK" = 1 ] || echo "$T: NOTE archive/site media copy did not complete (shared folder cap); the live site change is not affected"

# 2) page data (meeting 37 media + caption track); 3) shared build source (best effort)
python3 - "$A69" "$BUILD" <<'PY'
import json, os, sys
A69, BUILD = sys.argv[1:3]
T = os.environ.get('T_NAME', '189_pa37_post_video'); DUR = os.environ['DUR']
CC = "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ"
DAY = '2026-11-18'
dec = json.JSONDecoder()
SERS = [lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/'),
        lambda v: json.dumps(v, ensure_ascii=False),
        lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')),
        lambda v: json.dumps(v, ensure_ascii=False).replace('</', '<\\/')]
changed = []

def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.basename(path))

class Page:
    def __init__(self, path):
        self.path = path; self.lines = open(path, encoding='utf-8').read().split('\n')
    def edit(self, pfx, fn):
        idx = [k for k, l in enumerate(self.lines) if l.startswith(pfx)]
        assert len(idx) == 1, f'{os.path.basename(self.path)}: {pfx} not found once'
        l = self.lines[idx[0]]; v, e = dec.raw_decode(l[len(pfx):]); rest = l[len(pfx) + e:]
        ser = next((s for s in SERS if pfx + s(v) + rest == l), None)
        assert ser, f'{os.path.basename(self.path)}: {pfx} does not round-trip; not touching it'
        self.lines[idx[0]] = pfx + ser(fn(v)) + rest
    def save(self):
        put(self.path, '\n'.join(self.lines))

# same fields and order as the live after-meeting entry of meeting 36
P = dict(src="media/v37post.mp4", poster="img/poster37post.jpg", vtt="media/v37post.th.vtt", kind="post",
         label="วิดีโอสรุปผลการประชุม", dur=DUR, cc=CC, ck="37", size=os.path.getsize(os.path.join(A69, 'media/v37post.mp4')))

def media(md):
    md = dict(md or {})
    vids = [v for v in (md.get('videos') or []) if v.get('src') != P['src']]
    assert not any(v.get('kind') == 'post' for v in vids), 'meeting 37: another after-meeting video is already there'
    vids = [P] + vids                          # after-meeting first, before-meeting last (as meeting 36)
    md['videos'] = vids; md['video'] = P
    return md

def set_media(arr):
    hit = [m for m in arr if (m['n'], m['date']) == (37, DAY)]
    assert len(hit) == 1, 'meeting 37 not found once'
    hit[0]['media'] = media(hit[0].get('media'))
    return arr

vt = open(os.path.join(A69, 'media', 'v37post.th.vtt'), encoding='utf-8').read(); assert '</' not in vt

def caps(c):
    out = {}
    for k, x in c.items():
        if k == '37':
            continue
        if k == '37p':
            out['37'] = vt
        out[k] = x
    if '37' not in out:
        out['37'] = vt
    return out

pg = Page(os.path.join(A69, 'index.html'))
pg.edit('const DATA=', set_media)
pg.edit('const CAPS=', caps)
pg.save()
p = os.path.join(A69, 'meetings.json'); raw = open(p, encoding='utf-8').read(); sj = json.loads(raw)
assert json.dumps(sj, ensure_ascii=False, indent=1) == raw, 'meetings.json does not round-trip; not touching it'
put(p, json.dumps(set_media(sj), ensure_ascii=False, indent=1))
print(f'{T}: archive changed', len(changed), 'files:', ', '.join(changed) or 'none (already applied)')

try:
    bp = os.path.join(BUILD, 'build.py'); bt = open(bp, encoding='utf-8').read(); bn = bt
    if 'media/v37post.mp4' not in bt:
        old = ('    37: dict(src="media/v37.mp4", poster="img/poster37.jpg", vtt="media/v37.th.vtt", kind="pre",\n'
               '             label="วิดีโอก่อนการประชุม", dur="1:58", cc="เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ"),\n')
        assert bt.count(old) == 1, 'build.py: VIDEOS[37] (pre only) not found once'
        new = ('    # 37 after-meeting video: 23 Nov 2569, bundle item ' + T + ' (EN burned in).\n'
               '    37: [dict(src="media/v37post.mp4", poster="img/poster37post.jpg", vtt="media/v37post.th.vtt", kind="post",\n'
               f'              label="วิดีโอสรุปผลการประชุม", dur="{DUR}", cc="เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ"),\n'
               '         dict(src="media/v37.mp4", poster="img/poster37.jpg", vtt="media/v37.th.vtt", kind="pre",\n'
               '              label="วิดีโอก่อนการประชุม", dur="1:58", cc="เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ")],\n')
        bn = bt.replace(old, new, 1)
        open(bp, 'w', encoding='utf-8').write(bn); assert open(bp, encoding='utf-8').read() == bn
    print(f'{T}: shared build', 'updated' if bn != bt else 'already in step')
except Exception as e:                                   # never blocks the site change
    print(f'{T}: NOTE shared build source not updated ({e}); the live site change is not affected')
PY

# 4) video share page + card for the after video; every existing share page kept byte-identical (video_share.py rewrites all);
#    on the new page the no-download block goes back in front of the alerts block, the same layout as the live pages
KEEP="$TMP/keep"; mkdir -p "$KEEP"
NEWP="v-37.html"
for f in "$A69"/s/v-*.html; do b=$(basename "$f"); case " $NEWP " in *" $b "*) ;; *) cp -p "$f" "$KEEP/$b";; esac; done
CARD_BIG=1 python3 "$BUILD/video_share.py" "$A69" https://parliamentx.com/committee-archive-2569 2569
python3 "$BUILD/no_video_dl.py" "$A69/s"
for f in "$KEEP"/*.html; do [ -f "$f" ] || continue; cmp -s "$f" "$A69/s/$(basename "$f")" || cp -f "$f" "$A69/s/$(basename "$f")"; done
test -f "$A69/s/v-37.html" || { echo "$T: share page v-37.html missing" >&2; exit 1; }
python3 - "$A69/s/v-37.html" <<'PY'
import sys
p = sys.argv[1]; t = open(p, encoding='utf-8').read()
nv = t[t.index('<!--NOVDL-->'):t.index('<!--/NOVDL-->') + len('<!--/NOVDL-->') + 1]
if '<!--ALERTS_CTA-->' in t and t.index('<!--ALERTS_CTA-->') < t.index('<!--NOVDL-->'):
    t = t.replace(nv, '', 1); t = t.replace('<!--ALERTS_CTA-->', nv + '<!--ALERTS_CTA-->', 1)
    open(p, 'w', encoding='utf-8').write(t)
PY
python3 "$BUILD/no_video_dl.py" --check "$A69"
grep -q '"37":"s/v-37.html' "$A69/index.html" || { echo "$T: VSHARE[37] does not point to the after-meeting page" >&2; exit 1; }

# 5) home page "latest videos" list (newest 4 by meeting date; same entry shape as the live list)
python3 - "$HUB" "$A69" <<'PY'
import json, os, sys
HUB, A69 = sys.argv[1:3]
T = '189_pa37_post_video'
ser = lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')
m = [x for x in json.load(open(os.path.join(A69, 'meetings.json'), encoding='utf-8')) if (x['n'], x['date']) == (37, '2026-11-18')][0]
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); t0 = t; dec = json.JSONDecoder()
mark = 'const HH = '; assert t.count(mark) == 1, 'home: HH not found once'
hh, _ = dec.raw_decode(t[t.index(mark) + len(mark):])
old_s = ser(hh['videos']); assert t.count(old_s) == 1, 'home: video list text not found once'
base = 'committee-archive-2569/'
new = [dict(n=m['n'], date=m['date'], year=2569, who='กมธ.การบริหารราชการแผ่นดิน', label=v.get('label') or 'วิดีโอสรุป',
            dur=v.get('dur', ''), poster=base + v['poster'], headline='' if m.get('pending') else (m.get('headline') or ''),
            href=base + f"#read-{m['n']}") for v in m['media']['videos']]
vids = list(hh['videos']); seen = {(v['href'], v['poster']) for v in vids}
for v in new:
    if (v['href'], v['poster']) in seen:
        continue
    at = next((k for k, x in enumerate(vids) if x['href'] == v['href']), len(vids))
    vids.insert(at, v)
vids.sort(key=lambda v: v['date'], reverse=True)
t = t.replace(old_s, ser(vids[:4]), 1)
if t != t0:
    open(p, 'w', encoding='utf-8').write(t)
print(f'{T}: home list', 'changed' if t != t0 else 'unchanged (not in the newest 4, or already applied)')
PY
echo "$T: done"
exit 0
__PAYLOAD_BELOW__
